// APlus Academy Core 2 acronym glossary. Every acronym used in the lessons, deep dives, and cheat sheet, plus those in questions.
// Rendered by the engine as hover links in tutorials and the cheat sheet (tip on hover, more on click) and as the
// cheat sheet's Acronyms section. Keys are matched as whole words, case-sensitive, plurals allowed. Original wording.
// Fields: full (what it stands for), tip (one sentence for the tooltip), more (the longer explanation; blank line = new paragraph).
window.FRA = window.FRA || {};
FRA.acronyms = {
  "5G": { full: "Fifth-generation cellular", tip: "The current mobile network generation with higher speed and lower latency than LTE.", more: "5G uses new spectrum including millimeter wave for very high speeds over short range. Phones fall back to LTE where 5G is absent." },
  "802.1X": { full: "IEEE 802.1X", tip: "Port-based network access control: a device must authenticate before the switch port or Wi-Fi passes traffic.", more: "With 802.1X the client (supplicant) presents credentials or a certificate through the switch or access point (authenticator) to a RADIUS server (authentication server) using EAP. Until it succeeds, the port only passes authentication traffic. It is the basis of WPA2 and WPA3 Enterprise and of wired NAC." },
  "ABC": { full: "Class A, B, and C fire extinguisher", tip: "A multipurpose extinguisher for ordinary combustibles, flammable liquids, and electrical fires.", more: "Class A is wood and paper, B is liquids, C is energized electrical. An ABC dry chemical unit covers all three and is safe on a burning power supply." },
  "AC": { full: "Alternating current", tip: "Mains power, which reverses direction 60 times a second in North America.", more: "The power supply converts AC from the wall to the DC a computer uses. Old CCFL backlights need high-voltage AC from an inverter. In the CBET course AC theory covers RMS voltage, frequency, and why 60 Hz current is dangerous." },
  "ACL": { full: "Access control list", tip: "An ordered list of permit and deny rules on a router, firewall, or file system.", more: "On network devices an ACL filters packets by source, destination, protocol, and port, processed top down with the first match winning and an implicit deny at the end. On file systems an ACL lists which users and groups have which permissions on an object." },
  "AD": { full: "Active Directory", tip: "Microsoft's directory service: the domain's database of users, computers, and groups.", more: "Active Directory authenticates domain logons with Kerberos, stores accounts and groups in organizational units, and delivers Group Policy. Domain controllers run it." },
  "AES": { full: "Advanced Encryption Standard", tip: "The standard symmetric cipher, with 128, 192, or 256-bit keys.", more: "AES encrypts and decrypts with the same key and is fast enough to protect disks, Wi-Fi (WPA2 and WPA3), VPNs, and TLS sessions. AES-128 is secure; AES-256 is used for high-value data. It replaced DES and 3DES." },
  "AES-CCMP": { full: "AES in CCMP mode", tip: "The AES-based encryption WPA2 uses for Wi-Fi.", more: "CCMP is the mode that gives WPA2 both confidentiality and integrity with AES. When a question contrasts WPA2-AES with WPA-TKIP, this is what it means." },
  "AI": { full: "Artificial intelligence", tip: "Software that learns patterns and generates text, images, or decisions.", more: "AI tools help with scripting, documentation, and help-desk work, but their output must be checked and sensitive data must not be pasted into public services. Attackers use the same tools for convincing phishing." },
  "AP": { full: "Access point", tip: "The radio that bridges Wi-Fi clients onto the wired network.", more: "An access point turns Wi-Fi frames into Ethernet frames and back. Standalone (autonomous) APs are configured one by one; lightweight APs are managed by a wireless LAN controller. Each AP advertises one or more SSIDs, and clients roam between APs that share an SSID. In the CBET course the same letters also appear in anteroposterior X-ray views; read the context." },
  "APFS": { full: "Apple File System", tip: "The modern macOS and iOS file system with snapshots and encryption.", more: "APFS replaced HFS+ on Apple devices. It is optimized for SSDs and supports cloning, snapshots, and native encryption." },
  "APN": { full: "Access point name", tip: "The gateway setting a phone uses to reach a carrier's data network.", more: "Wrong APN settings mean cellular data does not work even with a strong signal. Carriers push them automatically; MDM can set them." },
  "ARP": { full: "Address Resolution Protocol", tip: "Finds the MAC address that goes with a known IPv4 address on the local segment.", more: "When a host knows the IP address of a neighbor but not its MAC address, it broadcasts an ARP request and the owner replies with its MAC. Hosts cache the answer in an ARP table. Because ARP has no authentication, attackers can poison the cache to redirect traffic, which is why switches offer dynamic ARP inspection. IPv6 replaces ARP with Neighbor Discovery." },
  "AUP": { full: "Acceptable use policy", tip: "The rules for how staff may use company systems and data.", more: "The AUP tells employees what is allowed on company devices and networks and what monitoring to expect. Signing it is usually part of onboarding." },
  "BEC": { full: "Business email compromise", tip: "Fraud by email impersonating an executive or vendor to redirect payments.", more: "The attacker spoofs or hijacks a trusted mailbox and asks finance to wire money or change bank details. It is social engineering, not malware, so the defenses are verification procedures and DMARC." },
  "BIOS": { full: "Basic Input/Output System", tip: "The original PC firmware: 16-bit, text setup, MBR disks up to 2 TB.", more: "BIOS initializes hardware, runs the power-on self-test, and hands off to the boot loader. It is limited to MBR disks and four primary partitions and has been replaced by UEFI, which many people still call the BIOS." },
  "BSOD": { full: "Blue screen of death", tip: "The Windows stop error screen from a driver or hardware fault.", more: "A BSOD shows a stop code and often a driver name. Repeated blue screens point to bad drivers, faulty RAM, or overheating; the stop code is the first clue." },
  "BYOD": { full: "Bring your own device", tip: "Staff use personal phones and laptops for work.", more: "BYOD saves the company money but mixes personal and corporate data on devices the company does not control. Mobile device management, containerization, and acceptable use policies define what the company may do on the device and what happens when someone leaves." },
  "CAD": { full: "Computer-aided design", tip: "Engineering and drafting software that needs a workstation-class GPU and RAM.", more: "CAD workstations are the exam's example of a machine built for graphics and memory rather than office use." },
  "CCMP": { full: "Counter Mode with Cipher Block Chaining Message Authentication Code Protocol", tip: "The AES-based encryption WPA2 uses.", more: "CCMP provides confidentiality and integrity for Wi-Fi frames using AES. When a question contrasts WPA2 with AES against WPA with TKIP, CCMP is the AES mode being referenced." },
  "CEO": { full: "Chief executive officer", tip: "The top executive; the person impersonated in whaling and business email compromise.", more: "Attacks that pose as the CEO exploit staff reluctance to question authority. Verification procedures for payment changes are the defense." },
  "CFO": { full: "Chief financial officer", tip: "The executive in charge of money; a common target and impersonation in payment fraud.", more: "An email from the CFO asking to wire funds to a new account is the classic business email compromise scenario." },
  "CMDB": { full: "Configuration management database", tip: "The inventory of IT assets and how they relate, used in change and incident management.", more: "A CMDB records every server, application, and network device with its dependencies, so the impact of a change or outage can be traced. Keeping it accurate is the hard part." },
  "CMOS": { full: "Complementary metal-oxide semiconductor", tip: "The small battery-backed memory that keeps firmware settings and the clock.", more: "The CMOS chip stores BIOS or UEFI settings and time, kept alive by a CR2032 coin cell. A dead cell resets the clock and settings at every boot. Clearing CMOS with a jumper resets a forgotten firmware password." },
  "CO2": { full: "Carbon dioxide", tip: "The gas in CO2 fire extinguishers, safe on electrical fires; in medicine, the gas measured by capnography.", more: "CO2 extinguishers smother a fire without residue, so they suit electrical equipment. In the CBET course CO2 is the end-tidal gas capnography measures and the medium of CO2 surgical lasers." },
  "CPU": { full: "Central processing unit", tip: "The processor that executes instructions.", more: "The CPU's cores, threads, clock speed, and cache set a computer's performance. Sudden CPU spikes are a security indicator for crypto mining or malware. In the A+ course you match its socket (LGA, PGA, AM4, AM5) to the motherboard and keep it cool." },
  "CRT": { full: "Cathode ray tube", tip: "The old glass-tube monitor; holds dangerous voltage even when unplugged.", more: "CRTs are obsolete but appear in safety questions: they store high voltage, so do not open one or wear a grounding strap while working inside." },
  "DC": { full: "Domain controller", tip: "The server that runs Active Directory and authenticates domain logons.", more: "Domain controllers hold the AD database and answer Kerberos and LDAP requests. A site needs at least two for redundancy." },
  "DDoS": { full: "Distributed denial of service", tip: "Many sources, usually a botnet, flood a target at once.", more: "DDoS attacks use thousands of compromised machines, or amplification through open DNS and NTP servers, to overwhelm a target. Defenses are upstream scrubbing services, CDNs, and rate limiting." },
  "DHCP": { full: "Dynamic Host Configuration Protocol", tip: "Hands out IP addresses, masks, gateways, and DNS servers automatically (UDP 67 and 68).", more: "A DHCP server leases addresses to clients through the DORA exchange: Discover, Offer, Request, Acknowledge. The lease also carries the subnet mask, default gateway, DNS servers, and options such as a TFTP server. Because Discover is a broadcast, a router needs a relay (IP helper) to reach a server on another subnet. Reservations tie a fixed address to a MAC; scopes and exclusions define the pool." },
  "DISM": { full: "Deployment Image Servicing and Management", tip: "The Windows tool that repairs the component store and services images.", more: "When System File Checker cannot repair files, DISM with the RestoreHealth option fixes the underlying component store from Windows Update or an image. It also adds drivers and features to installation images." },
  "DLP": { full: "Data loss prevention", tip: "Tools that detect and block sensitive data leaving by email, web, USB, or cloud.", more: "DLP inspects content for patterns such as card numbers or classification labels and blocks or logs the transfer. It works on endpoints, email gateways, and cloud services. Files copied to USB drives being blocked is DLP." },
  "DMA": { full: "Direct memory access", tip: "Devices move data to and from memory without going through the CPU.", more: "DMA speeds up disks and network cards. Attacks over DMA-capable ports such as Thunderbolt are why kernel DMA protection exists." },
  "DMZ": { full: "Demilitarized zone", tip: "A screened subnet between the internet and the internal network for public-facing servers.", more: "A DMZ holds web, mail, and other servers that outsiders must reach. Firewalls allow the internet to reach the DMZ, and tightly restrict the DMZ's access to the inside, so a compromised public server does not give an attacker the internal LAN. The modern term is screened subnet." },
  "DNS": { full: "Domain Name System", tip: "Translates names such as www.example.com into IP addresses (UDP 53, TCP 53 for zone transfers).", more: "DNS is a distributed database of names. A resolver asks recursive servers, which walk from the root to the top-level domain to the authoritative server for the zone. Record types include A (IPv4), AAAA (IPv6), CNAME (alias), MX (mail), PTR (reverse), TXT (text such as SPF), SRV (service location), NS, and SOA. If a site works by IP address but not by name, DNS is the problem." },
  "DoH": { full: "DNS over HTTPS", tip: "DNS queries carried inside HTTPS on TCP 443 so they cannot be read or altered in transit.", more: "DoH wraps DNS inside an ordinary HTTPS connection to a resolver. Browsers and operating systems support it, and because it looks like web traffic it is hard for a network to block or inspect. It protects privacy between the client and the resolver; it does not sign the records themselves." },
  "DoS": { full: "Denial of service", tip: "One source floods or crashes a target so it cannot serve users.", more: "A DoS attack exhausts bandwidth, connections, or CPU. Because it comes from one source it can be filtered; distributed attacks from many sources are far harder." },
  "DRM": { full: "Digital rights management", tip: "Technology that restricts copying and use of licensed content and software.", more: "DRM ties media or software to a device or account. It appears on the exam under licensing and regulated content." },
  "DSS": { full: "Data Security Standard", tip: "The PCI DSS rules for protecting payment card data.", more: "PCI DSS requires firewalls, encryption of card data, access control, monitoring, and testing, with the cardholder data environment segmented from the rest of the network." },
  "DVD": { full: "Digital versatile disc", tip: "Optical media holding 4.7 GB, or 8.5 GB dual layer.", more: "DVDs succeeded CDs for software and video. Blu-ray raised capacity to 25 GB per layer." },
  "DWORD": { full: "Double word", tip: "A 32-bit registry value type.", more: "Most numeric registry settings are DWORDs. QWORD is the 64-bit type and SZ a string." },
  "EAP": { full: "Extensible Authentication Protocol", tip: "The framework that carries authentication methods inside 802.1X.", more: "EAP defines how credentials travel between the supplicant and the authentication server; the method (EAP-TLS, PEAP, EAP-TTLS, EAP-FAST) decides what proof is used." },
  "EDR": { full: "Endpoint detection and response", tip: "Endpoint agents that record activity, detect attacks, and let responders isolate and clean the machine.", more: "EDR goes beyond antivirus by watching process behavior, collecting telemetry, and giving analysts tools to investigate and contain a compromised host remotely." },
  "EFS": { full: "Encrypting File System", tip: "Per-file and per-folder encryption built into NTFS, tied to the user's account.", more: "EFS encrypts individual files so other users on the same machine cannot read them. Losing the user's key or profile loses the files unless a recovery agent exists. BitLocker encrypts the whole drive instead." },
  "EOL": { full: "End of life", tip: "The vendor stops selling the product.", more: "At end of life a product is no longer sold but may still receive support for a while. It is the first warning that planning for replacement should start." },
  "ESD": { full: "Electrostatic discharge", tip: "Static electricity that can destroy chips; prevented with a wrist strap, mat, and antistatic bags.", more: "A static shock you cannot feel can still kill a component. Wear a strap connected to ground, work on an antistatic mat, and keep parts in their bags. Never wear a strap inside a power supply or CRT, which hold lethal voltages." },
  "eSIM": { full: "Embedded SIM", tip: "A SIM built into the phone and provisioned by software.", more: "eSIM profiles are downloaded from the carrier, often via a QR code, so no physical card is needed and several profiles can coexist." },
  "EULA": { full: "End-user license agreement", tip: "The license terms a user accepts to install software.", more: "The EULA states what the buyer may do with the software: number of installs, personal or commercial use, and restrictions. Violating it is a compliance problem." },
  "exFAT": { full: "Extended File Allocation Table", tip: "A FAT variant for flash media with no 4 GB file limit.", more: "exFAT is the format for large SD cards and USB drives that must hold big video files and still work on Windows, macOS, and cameras." },
  "ext4": { full: "Fourth extended file system", tip: "The common Linux file system.", more: "ext4 is the default on most Linux distributions, with journaling and large volume support. XFS is the other common choice, especially on Red Hat systems." },
  "FAT": { full: "File Allocation Table", tip: "The family of simple file systems (FAT16, FAT32, exFAT).", more: "FAT keeps a table of which clusters each file uses. It has no permissions or journaling, which makes it portable and fragile." },
  "FAT32": { full: "File Allocation Table 32-bit", tip: "The simple, universal file system for USB drives; 4 GB file limit, no permissions.", more: "FAT32 is readable by every operating system, camera, and TV, so removable media use it. Its limits are files under 4 GB and volumes up to 2 TB (32 GB when formatted by Windows). exFAT removes the file size limit." },
  "FRT": { full: "Facial recognition technology", tip: "Biometric authentication by face.", more: "Facial recognition unlocks phones and laptops. Like all biometrics it has false acceptance and false rejection rates and cannot be changed if compromised." },
  "FTP": { full: "File Transfer Protocol", tip: "Plaintext file transfer on TCP 21 (control) and 20 (data); replace with SFTP or FTPS.", more: "FTP sends usernames, passwords, and files in the clear and needs a second connection for data, which complicates firewalls. Active mode has the server connect back to the client; passive mode has the client open both. It survives on legacy systems only." },
  "GB": { full: "Gigabyte", tip: "About a billion bytes; the unit for RAM, storage, and data caps.", more: "A gigabyte is 1,000 or 1,024 megabytes depending on whether the maker counts in decimal or binary. RAM is sold in GB, and 32-bit systems can address only about 4 GB." },
  "GFS": { full: "Grandfather-father-son", tip: "A backup rotation with daily, weekly, and monthly sets kept for increasing periods.", more: "GFS keeps sons (daily) for a week, fathers (weekly) for a month, and grandfathers (monthly) for a year or more, balancing retention against media cost." },
  "GHz": { full: "Gigahertz", tip: "Billions of cycles per second; CPU clock speed and Wi-Fi band frequency.", more: "A 3.5 GHz CPU ticks 3.5 billion times a second. Wi-Fi uses the 2.4, 5, and 6 GHz bands, where higher frequency means more bandwidth but shorter range and worse wall penetration." },
  "GPO": { full: "Group Policy Object", tip: "A set of Windows settings applied to users and computers, locally or through Active Directory.", more: "GPOs enforce password rules, software restrictions, drive mappings, and hundreds of other settings. Domain GPOs are linked to sites, domains, and organizational units and override local policy." },
  "GPT": { full: "GUID Partition Table", tip: "The modern disk partition scheme: any disk size, up to 128 partitions, required for UEFI boot.", more: "GPT replaced MBR's 2 TB limit and four-partition limit and stores backup partition tables for resilience. Windows converts a disk with MBR2GPT when moving from BIOS to UEFI." },
  "GPU": { full: "Graphics processing unit", tip: "The processor that renders images; on a card or built into the CPU.", more: "A discrete GPU on a PCIe x16 card needs its own power connectors and drives high resolutions and games. Integrated graphics share the CPU and system memory and suit office work." },
  "GRUB": { full: "Grand Unified Bootloader", tip: "The Linux boot loader that presents the kernel menu.", more: "GRUB loads the Linux kernel and can dual-boot Windows. A broken GRUB leaves a system at a rescue prompt; reinstalling it from live media fixes it." },
  "GUI": { full: "Graphical user interface", tip: "Windows, icons, and a mouse, as opposed to a command line.", more: "Most management tools have a GUI and a command-line equivalent. Web interfaces on network devices are GUIs over HTTPS." },
  "GUID": { full: "Globally unique identifier", tip: "A 128-bit random identifier used for partitions, objects, and records.", more: "GUIDs name GPT partitions, Active Directory objects, and registry classes. The probability of two colliding is effectively zero." },
  "HDD": { full: "Hard disk drive", tip: "Spinning magnetic storage: cheap per terabyte, slower, and fragile.", more: "HDDs spin platters at 5400 or 7200 rpm and read them with a moving head, so they are slow to seek and vulnerable to shock. Clicking, slow response, and S.M.A.R.T. warnings mean replace it and restore from backup." },
  "HFS+": { full: "Hierarchical File System Plus", tip: "The older macOS file system, replaced by APFS.", more: "HFS+ was the Mac file system for two decades. Modern Macs use APFS, but external drives may still be HFS+." },
  "HIPAA": { full: "Health Insurance Portability and Accountability Act", tip: "The US law protecting health information and setting privacy and security rules.", more: "HIPAA's Privacy Rule governs use of protected health information and its Security Rule requires administrative, physical, and technical safeguards. Breaches must be reported, and business associates that handle the data are directly liable." },
  "HKCU": { full: "HKEY_CURRENT_USER", tip: "The registry hive holding the logged-in user's settings.", more: "HKCU is a view of the current user's profile hive: desktop settings, per-user software configuration, and per-user startup entries." },
  "HKLM": { full: "HKEY_LOCAL_MACHINE", tip: "The registry hive holding machine-wide settings.", more: "HKLM stores hardware, driver, and installed-software settings that apply to every user. Startup programs for all users live under its Run keys." },
  "HR": { full: "Human resources", tip: "The department that hires and separates staff; its system should drive account provisioning and removal.", more: "Tying account creation and deprovisioning to HR records closes the gap where former employees keep access." },
  "HTTP": { full: "Hypertext Transfer Protocol", tip: "Web traffic in the clear on TCP 80.", more: "HTTP carries web pages and API calls without encryption, so anything sent can be read on the path. HTTPS on 443 is the secure form, and modern sites redirect to it." },
  "HTTPS": { full: "Hypertext Transfer Protocol Secure", tip: "HTTP inside TLS on TCP 443.", more: "HTTPS encrypts web traffic and lets the browser verify the server's certificate. The padlock means the connection to that server is private, not that the site is honest. DoH also rides on 443." },
  "IAM": { full: "Identity and access management", tip: "The systems and processes for creating accounts, authenticating users, and granting permissions.", more: "IAM covers provisioning and deprovisioning, authentication including MFA, single sign-on, federation, and least-privilege authorization. Automated deprovisioning tied to HR closes the gap when someone leaves." },
  "ID": { full: "Identifier or identification", tip: "A name or number that uniquely labels a user, device, session, or record.", more: "IDs appear everywhere: user IDs, VLAN IDs, process IDs, patient IDs, and caller ID, which can be spoofed. The exam mostly tests that an ID by itself is not proof of identity." },
  "iOS": { full: "iPhone operating system", tip: "Apple's mobile operating system for iPhone.", more: "iOS is tightly controlled: apps come from the App Store and are sandboxed. Jailbreaking removes those restrictions and the protection that comes with them. iPadOS is the tablet variant." },
  "IP": { full: "Internet Protocol", tip: "The Layer 3 protocol that addresses and routes packets between networks.", more: "IP gives every host a logical address and lets routers forward packets from network to network using that address. Version 4 uses 32-bit addresses written as four numbers; version 6 uses 128-bit addresses written in hex. IP itself is best effort: it does not guarantee delivery, which is why TCP exists above it." },
  "iPadOS": { full: "iPad operating system", tip: "Apple's tablet operating system, a variant of iOS.", more: "iPadOS shares its foundation and security model with iOS, adding multitasking features for the larger screen." },
  "IPsec": { full: "Internet Protocol Security", tip: "The suite that encrypts and authenticates IP packets for VPNs.", more: "IPsec uses AH for integrity, ESP for encryption plus integrity, and IKE to negotiate keys. Transport mode protects the payload between two hosts; tunnel mode wraps the whole packet for site-to-site VPNs. ESP is IP protocol 50, AH is 51, IKE uses UDP 500 and 4500 for NAT traversal." },
  "IPv6": { full: "Internet Protocol version 6", tip: "128-bit addresses in eight hex groups; no broadcast, built-in autoconfiguration.", more: "IPv6 uses 128-bit addresses written as hex groups separated by colons, with rules for shortening runs of zeros. There is no broadcast; multicast and neighbor discovery take its place. Hosts can build their own address from a router advertisement (SLAAC). Link-local addresses start with fe80, and the loopback is ::1." },
  "IRQ": { full: "Interrupt request", tip: "The signal a device uses to get the CPU's attention.", more: "IRQs let hardware interrupt the processor. Modern plug-and-play assigns them automatically; the term survives in stop codes such as IRQL_NOT_LESS_OR_EQUAL." },
  "IRQL": { full: "Interrupt request level", tip: "The priority level of Windows kernel code; a common stop code names it.", more: "IRQL_NOT_LESS_OR_EQUAL is a blue screen usually caused by a driver touching memory it should not, or by bad RAM." },
  "ISO": { full: "International Organization for Standardization; also an ISO disc image", tip: "The standards body, and the .iso file format that holds a complete disc image.", more: "ISO 9001 is the quality management standard some hospital accreditors use. An ISO file is a disc image you attach to a virtual machine or write to a USB stick to install an operating system." },
  "ISP": { full: "Internet service provider", tip: "The company that connects you to the internet.", more: "The ISP supplies the WAN link, public addresses, and often DNS. Guaranteed uptime from the ISP is an SLA." },
  "IT": { full: "Information technology", tip: "Computers, networks, and the people who run them.", more: "IT is the department and the discipline that runs business systems. On the exam it appears in shadow IT (systems staff set up without approval) and in the contrast with operational technology." },
  "JIT": { full: "Just-in-time access", tip: "Privileges are granted only when needed and removed afterward.", more: "JIT access replaces standing administrator rights with temporary elevation approved per task, shrinking the window in which stolen credentials are useful." },
  "KB": { full: "Kilobyte", tip: "About a thousand bytes.", more: "Small files, registry values, and packet sizes are measured in KB." },
  "KDC": { full: "Key Distribution Center", tip: "The Kerberos service on a domain controller that issues tickets.", more: "The KDC authenticates the user once and issues a ticket-granting ticket, then service tickets for each resource, so the password is never sent to individual servers." },
  "KVM": { full: "Kernel-based Virtual Machine, or a keyboard-video-mouse switch", tip: "The Linux kernel's built-in hypervisor; also the switch that shares one console among computers.", more: "As a hypervisor, KVM turns Linux into a type 1 host managed with QEMU and libvirt. As hardware, a KVM switch lets one keyboard, monitor, and mouse control several machines. Read the context." },
  "L2TP": { full: "Layer 2 Tunneling Protocol", tip: "A VPN tunneling protocol that needs IPsec for encryption (L2TP/IPsec).", more: "L2TP creates the tunnel and IPsec protects it. It is widely supported but often blocked by NAT and has been overtaken by IKEv2." },
  "LAN": { full: "Local area network", tip: "One site's network: a building, floor, or campus that one organization owns and runs.", more: "A LAN is the network inside one location, usually built from switches and Ethernet or Wi-Fi, running at high speed because the organization owns every piece of it. When a question says one office, one building, or one campus, it is describing a LAN. Anything that crosses a provider's link to reach another city is no longer a LAN." },
  "LDAP": { full: "Lightweight Directory Access Protocol", tip: "Queries a directory such as Active Directory for users and groups; TCP 389, secure 636.", more: "LDAP is how applications look up accounts, group memberships, and attributes in a directory. Plain LDAP sends binds in the clear, so LDAPS on 636 or StartTLS should be used. Kerberos handles the actual Windows logon; LDAP handles lookups." },
  "LTO": { full: "Linear Tape-Open", tip: "The standard tape format for backups and archives.", more: "LTO tapes hold many terabytes cheaply and last decades offline, which makes them the choice for long-term retention and air-gapped copies." },
  "MAC": { full: "Media access control (address)", tip: "The 48-bit hardware address burned into a network interface, used at Layer 2.", more: "A MAC address is the physical address of a network card, written as six pairs of hex digits. The first half is the manufacturer code (OUI). Switches build a table of which MAC address is on which port and forward frames by it. MAC addresses only matter within one LAN segment; routers use IP addresses to move packets between networks. In Security+ the same letters can also mean mandatory access control." },
  "macOS": { full: "Mac operating system", tip: "Apple's desktop operating system.", more: "macOS runs on Apple hardware, uses APFS, installs apps from the App Store or disk images, and offers Time Machine backups, Keychain, FileVault encryption, and Spotlight search." },
  "MBR": { full: "Master boot record", tip: "The legacy partition scheme: disks up to 2 TB, four primary partitions, BIOS boot.", more: "The MBR sits in the first sector and holds the boot code and the partition table. Its limits are why UEFI systems use GPT." },
  "MBR2GPT": { full: "MBR to GPT conversion tool", tip: "The Windows command that converts a disk from MBR to GPT without data loss.", more: "Run MBR2GPT before switching firmware from legacy BIOS to UEFI so the disk can still boot." },
  "MDM": { full: "Mobile device management", tip: "Software that enrolls phones and tablets and enforces policy: passcodes, encryption, apps, remote wipe.", more: "An MDM platform lets the organization configure and secure mobile devices, corporate or personal. It can push settings, restrict apps, locate devices, and wipe a lost one, either fully or just the corporate container." },
  "MDR": { full: "Managed detection and response", tip: "An outsourced team that monitors your EDR or XDR and responds around the clock.", more: "MDR providers run the tools and the analysts for organizations that cannot staff a security operations center." },
  "MDT": { full: "Microsoft Deployment Toolkit", tip: "Free Microsoft tooling for building and deploying Windows images.", more: "MDT automates unattended installs, driver injection, and application deployment, often with PXE boot." },
  "MFA": { full: "Multi-factor authentication", tip: "Two or more different kinds of proof: something you know, have, are, or where you are.", more: "MFA combines factors from different categories, such as a password plus a code from a phone app. Two passwords are still one factor. It defeats stolen passwords because the attacker lacks the second factor, and it is the standard fix for account takeover in exam scenarios." },
  "MMC": { full: "Microsoft Management Console", tip: "The framework that hosts administrative snap-ins such as Device Manager and Event Viewer.", more: "Tools ending in .msc are MMC snap-ins. A custom console can combine several for one administrator's needs." },
  "MNDA": { full: "Mutual non-disclosure agreement", tip: "An NDA that binds both parties equally.", more: "A mutual NDA protects confidential information flowing in both directions between partners." },
  "MSDS": { full: "Material safety data sheet", tip: "The older name for the safety data sheet.", more: "MSDS was renamed SDS when the globally harmonized system standardized the format." },
  "NAS": { full: "Network-attached storage", tip: "A file server appliance that shares folders over the regular network using SMB or NFS.", more: "A NAS is a box of disks with its own small operating system that shares files over the LAN. Clients see shared folders, not raw disks, which is the file-level versus block-level distinction from a SAN. Small offices use a NAS for shared documents and backups." },
  "NAT": { full: "Network address translation", tip: "Rewrites private inside addresses to a public address at the router so many hosts can share it.", more: "NAT lets a network use private RFC 1918 addresses internally while presenting one or a few public addresses to the internet. The router keeps a table mapping each inside connection to the outside address and port. Static NAT maps one address to one; dynamic NAT uses a pool; PAT (port address translation) lets a whole network share one public address by varying ports." },
  "NDA": { full: "Non-disclosure agreement", tip: "A contract that keeps shared information confidential.", more: "NDAs protect trade secrets and sensitive data when vendors, partners, or new employees are given access. Violations are a legal matter, which is why they appear alongside other agreements on the exam." },
  "NFC": { full: "Near-field communication", tip: "Very short range radio (about 4 cm) at 13.56 MHz for tap-to-pay and badge readers.", more: "NFC powers contactless payment, transit cards, and quick pairing. Its short range is part of its security." },
  "NFO": { full: "System Information file", tip: "The .nfo file saved by msinfo32 with a full hardware and software inventory.", more: "Exporting an NFO from System Information captures everything about a machine for a support ticket or an asset record." },
  "NIC": { full: "Network interface card", tip: "The adapter that connects a computer to the network, wired or wireless.", more: "A NIC has a MAC address and link lights. Teaming two NICs gives redundancy. A failing NIC, a speed or duplex mismatch, or a bad driver are standard troubleshooting suspects." },
  "NLA": { full: "Network Level Authentication", tip: "Remote Desktop authenticates the user before showing a logon screen.", more: "NLA makes RDP refuse the connection until the user has authenticated, reducing exposure to attacks on the logon screen. It should stay enabled." },
  "NTFS": { full: "New Technology File System", tip: "The standard Windows file system: permissions, encryption, compression, large files, journaling.", more: "NTFS supports per-user permissions, EFS encryption, quotas, and files larger than 4 GB, and it recovers from crashes with its journal. FAT32 lacks all of that but works on every device, which is why USB sticks still use it." },
  "NTP": { full: "Network Time Protocol", tip: "Synchronizes clocks across the network (UDP 123); wrong time breaks Kerberos, certificates, and logs.", more: "NTP keeps every device's clock aligned to a reference. Stratum 0 is the reference clock (GPS, atomic), stratum 1 servers connect to it, and each hop adds one. Kerberos fails when clocks differ by more than five minutes, certificates look expired, and logs cannot be correlated. NTS adds authentication. In the CBET course the same letters also name the National Toxicology Program; read the context." },
  "NVMe": { full: "Non-Volatile Memory Express", tip: "The fast SSD interface that talks to PCIe lanes directly, usually in an M.2 slot.", more: "NVMe drives reach several thousand MB/s, many times a SATA SSD's 550 MB/s. An M.2 slot must support NVMe (M key, PCIe lanes) rather than SATA for the drive to work." },
  "OS": { full: "Operating system", tip: "The software that manages hardware and runs applications: Windows, macOS, Linux, iOS, Android.", more: "The OS controls processes, memory, files, and devices. Keeping it patched and hardened is the first endpoint defense. In cloud terms, with IaaS you manage the OS and the provider manages the hardware." },
  "OSHA": { full: "Occupational Safety and Health Administration", tip: "The US agency that sets workplace safety rules.", more: "OSHA rules cover hazard communication, electrical safety, bloodborne pathogens, and lifting. Its Hazard Communication Standard is why safety data sheets exist." },
  "OTP": { full: "One-time password", tip: "A code that is valid for a single login.", more: "OTPs come from apps (time-based), hardware tokens, or SMS. SMS delivery is the weakest because phone numbers can be hijacked." },
  "OU": { full: "Organizational unit", tip: "A container in Active Directory used to group users and computers so policies and delegation can target them.", more: "OUs let administrators apply Group Policy to just the sales department or delegate password resets for one office. They mirror the organization's structure inside the domain." },
  "PAC": { full: "Proxy auto-configuration file", tip: "A script that tells the browser which proxy to use for each URL.", more: "A PAC file is fetched from a URL or found by WPAD and decides per request whether to go direct or through a proxy." },
  "PAM": { full: "Privileged access management", tip: "Controls and records the use of administrator accounts.", more: "PAM vaults privileged credentials, checks them out for a time-limited session, records what was done, and rotates passwords afterward, so admin rights are used just in time rather than held permanently." },
  "PC": { full: "Personal computer", tip: "A desktop or laptop for one user.", more: "The PC is the machine the A+ exam takes apart: motherboard, CPU, RAM, storage, power supply, and ports. In networking questions it is the client behind the phone or on the switch port." },
  "PCI": { full: "Peripheral Component Interconnect", tip: "The older expansion bus; PCIe (PCI Express) is its modern serial successor.", more: "PCIe slots come in x1, x4, x8, and x16 lengths, with x16 for graphics cards and x4 for NVMe drives. A card works in a longer slot. In Security+ PCI refers to the payment card industry; read the context." },
  "PID": { full: "Process identifier", tip: "The number the operating system gives each running process.", more: "Task Manager and the tasklist command show PIDs, and taskkill ends a process by it." },
  "PII": { full: "Personally identifiable information", tip: "Data that identifies a person: name, address, Social Security number, date of birth.", more: "PII must be protected under privacy laws and breach-notification rules. Handling it requires encryption, access control, and care in disposal." },
  "PIN": { full: "Personal identification number", tip: "A short numeric secret, a something-you-know factor.", more: "A PIN unlocks a phone, a SIM, or a smart card. A password plus a PIN is still one factor because both are things you know." },
  "POST": { full: "Power-on self-test", tip: "The firmware's hardware check at power-up; failures show as beep codes or a POST card reading.", more: "POST tests the CPU, memory, and video before anything boots. A board that refuses to POST is signaling a hardware problem, and the beep pattern or a POST card in a slot tells you which." },
  "PSK": { full: "Pre-shared key", tip: "One shared passphrase for everyone on a Wi-Fi network (Personal mode).", more: "A PSK is the Wi-Fi password typed into every device. It is simple but weak for organizations: everyone knows it, and revoking one person means changing it everywhere. Enterprise mode with 802.1X and RADIUS gives each user their own credentials." },
  "PSU": { full: "Power supply unit", tip: "Converts wall AC to the DC voltages a computer needs: 12 V, 5 V, 3.3 V.", more: "The PSU is rated in watts and must cover the CPU, graphics card, and drives with margin. Connectors include the 24-pin main, EPS 4 or 8-pin CPU, PCIe 6 and 8-pin, SATA, and the newer 12VHPWR. Modular supplies let you attach only the cables you need. A PSU that dies of heat, or a paperclip test that will not start it, are classic scenarios." },
  "PUP": { full: "Potentially unwanted program", tip: "Software that rides along with a download: toolbars, adware, bundled utilities.", more: "PUPs are not always malicious but slow the machine, change settings, and open the door to worse. Malware scanners flag them separately." },
  "PXE": { full: "Preboot Execution Environment", tip: "Booting a computer from the network to install or image an operating system.", more: "PXE lets the NIC fetch a boot image from a server via DHCP and TFTP, which is how deployment tools image many machines at once." },
  "QEMU": { full: "Quick Emulator", tip: "The open-source machine emulator often paired with KVM.", more: "QEMU emulates hardware for virtual machines and, with KVM, runs them at near-native speed." },
  "QR": { full: "Quick response code", tip: "The square barcode a phone camera reads.", more: "QR codes carry URLs, Wi-Fi credentials, or eSIM activation data. Attackers also abuse them to send people to malicious sites." },
  "RADIUS": { full: "Remote Authentication Dial-In User Service", tip: "The AAA server behind Wi-Fi Enterprise, VPNs, and 802.1X; UDP 1812 and 1813.", more: "A RADIUS server checks credentials for network access devices (switches, APs, VPN gateways) and tells them what the user is allowed. It encrypts only the password, uses UDP, and combines authentication and authorization, which is why TACACS+ is preferred for device administration." },
  "RAID": { full: "Redundant array of independent disks", tip: "Combining disks for speed, capacity, or fault tolerance: 0 stripe, 1 mirror, 5 stripe with parity, 6 double parity, 10 mirrored stripes.", more: "RAID 0 stripes data across disks for speed with no redundancy; one failure loses everything. RAID 1 mirrors two disks. RAID 5 stripes with one parity block and survives one disk failure (three disks minimum). RAID 6 has two parity blocks and survives two failures (four disks). RAID 10 mirrors pairs then stripes, needing four disks. RAID is availability, not backup." },
  "RAM": { full: "Random-access memory", tip: "The working memory that holds running programs and data; lost at power off.", more: "RAM speed and capacity limit how much a system can do at once. Because it is volatile, forensics collects it first (order of volatility) before the machine is powered down." },
  "RDP": { full: "Remote Desktop Protocol", tip: "Microsoft's remote graphical desktop on TCP 3389.", more: "RDP gives a full Windows desktop over the network. Exposed directly to the internet it is a frequent attack target, so it should sit behind a VPN or gateway with MFA and network level authentication." },
  "RFID": { full: "Radio-frequency identification", tip: "Tags read by radio for badges, inventory, and asset tracking.", more: "RFID badges open doors, and RFID tags track assets. Because tags answer any reader, cloning is possible, so high-security doors combine a badge with a PIN or biometric." },
  "RHEL": { full: "Red Hat Enterprise Linux", tip: "Red Hat's commercially supported Linux distribution.", more: "RHEL and its rebuilds use the rpm and dnf package tools and XFS by default. Debian-family systems such as Ubuntu use apt." },
  "RMM": { full: "Remote monitoring and management", tip: "Tools that managed service providers use to monitor, patch, and remotely control many computers.", more: "An RMM agent on each machine reports health, applies updates, runs scripts, and allows remote sessions. Attackers who compromise an RMM platform gain the same reach, so it must be secured with MFA." },
  "S.M.A.R.T": { full: "Self-Monitoring, Analysis, and Reporting Technology", tip: "Drive self-diagnostics that warn of impending failure.", more: "S.M.A.R.T. counters track reallocated sectors, temperature, and errors. A warning means back up now and replace the drive." },
  "SAE": { full: "Simultaneous authentication of equals", tip: "The WPA3 Personal handshake that resists offline password guessing.", more: "SAE is a password-authenticated key exchange, sometimes called Dragonfly. Both sides prove they know the passphrase without ever sending anything an eavesdropper could attack offline, and each session gets a fresh key. It is why WPA3 Personal is safe with a weaker passphrase than WPA2 would be." },
  "SAML": { full: "Security Assertion Markup Language", tip: "An XML standard for passing authentication between an identity provider and a web application (enterprise SSO).", more: "With SAML the application sends the user to the identity provider, which authenticates and returns a signed assertion listing who the user is and their attributes. It is the classic protocol for enterprise web single sign-on and federation." },
  "SCP": { full: "Secure Copy Protocol", tip: "Simple file copying over SSH, TCP 22.", more: "SCP copies files between hosts through an SSH connection with a command-line syntax like cp. It lacks SFTP's directory browsing but is quick for single files." },
  "SD": { full: "Secure Digital card", tip: "The flash memory card used in cameras and devices; miniSD and microSD are the smaller sizes.", more: "SD cards come in capacity classes (SDHC, SDXC) and speed classes. microSD with an adapter fits SD slots." },
  "SDS": { full: "Safety data sheet", tip: "The document describing a chemical's hazards, handling, and first aid; formerly MSDS.", more: "OSHA requires an SDS for every hazardous chemical in the workplace, from toner to cleaning agents. Staff must be able to reach it. The sixteen-section format comes from the GHS." },
  "SFTP": { full: "SSH File Transfer Protocol", tip: "File transfer inside an SSH session, TCP 22.", more: "SFTP is not FTP with encryption bolted on; it is a separate protocol carried over SSH. It uses one port, 22, which makes it firewall friendly, and it is the usual secure replacement for FTP." },
  "SHA-256": { full: "Secure Hash Algorithm 256-bit", tip: "The standard hash today: a 256-bit fingerprint of any input.", more: "SHA-256 is used in TLS certificates, code signing, file integrity, and password storage (with salting and stretching). Any change to the input changes the output completely, which is what makes it useful for integrity." },
  "SIM": { full: "Subscriber identity module", tip: "The card or embedded chip that identifies a phone to the cellular network.", more: "The SIM holds the subscriber identity and keys. eSIM is the embedded version, provisioned by downloading a profile (often by scanning a QR code). A SIM PIN locks the card; a carrier lock ties the phone to a network." },
  "SLA": { full: "Service level agreement", tip: "The contract stating measurable service commitments, such as 99.9% uptime.", more: "An SLA defines what a provider promises (availability, response time, repair time) and the penalties for missing it. Guaranteed uptime from the ISP is an SLA. Internal IT also uses SLAs for help desk response." },
  "SMB": { full: "Server Message Block", tip: "Windows file and printer sharing on TCP 445.", more: "SMB is the protocol behind mapped drives and shared printers. Version 1 is insecure and should be disabled; versions 2 and 3 add signing and encryption. Blocking 445 at the perimeter stops most worm-style spread." },
  "SMS": { full: "Short Message Service", tip: "Text messages; used for one-time codes and also a phishing channel (smishing).", more: "SMS codes are a common but weak second factor because SIM swapping and interception can steal them. Smishing is phishing by text message." },
  "SOHO": { full: "Small office, home office", tip: "A small network with a consumer-grade router doing NAT, DHCP, Wi-Fi, and firewall in one box.", more: "SOHO routers are the all-in-one devices the A+ exam configures: change the default password, set WPA3, update firmware, and forward ports only when needed." },
  "SOP": { full: "Standard operating procedure", tip: "A documented, step-by-step way of doing a routine task.", more: "SOPs make work repeatable and auditable: how to onboard a user, how to image a laptop, how to respond to a malware alert. New staff follow them; audits check them." },
  "SPICE": { full: "Simple Protocol for Independent Computing Environments", tip: "An open remote display protocol for virtual machines.", more: "SPICE connects to KVM virtual machine consoles with audio and USB redirection." },
  "SQL": { full: "Structured Query Language", tip: "The language used to query databases; also the name of the servers on TCP 1433 (Microsoft) and 3306 (MySQL).", more: "SQL is how applications read and write relational databases. On the exam it appears as the database server ports and, in security, as SQL injection, where untrusted input is pasted into a query and changes what it does." },
  "SSD": { full: "Solid-state drive", tip: "Flash storage with no moving parts: fast, silent, and shock resistant.", more: "SATA SSDs reach about 550 MB/s; NVMe SSDs several thousand MB/s. TRIM keeps them fast by telling the drive which blocks are free. They wear with writes but far outlast most systems." },
  "SSH": { full: "Secure Shell", tip: "Encrypted remote command-line access and file transfer on TCP 22; replaces Telnet and FTP.", more: "SSH authenticates with passwords or keys and encrypts the whole session. SFTP and SCP ride on it for file copies. Any question about managing a switch or server securely from the command line wants SSH." },
  "SSID": { full: "Service set identifier", tip: "The Wi-Fi network name that access points broadcast and clients join.", more: "The SSID is the human-readable network name, up to 32 characters. One AP can advertise several SSIDs, each mapped to a different VLAN, for example staff and guest. Hiding the SSID stops it appearing in scan lists but is not security, because clients still send it in the clear when they connect." },
  "SSO": { full: "Single sign-on", tip: "Log in once and reach many systems without signing in again.", more: "SSO lets an identity provider vouch for the user to every application, using protocols such as SAML, OAuth, and OpenID Connect. It improves convenience and lets one strong login with MFA protect everything, at the cost of that login becoming a high-value target." },
  "SSTP": { full: "Secure Socket Tunneling Protocol", tip: "Microsoft's VPN protocol that carries PPP inside TLS on port 443.", more: "SSTP passes through most firewalls because it looks like HTTPS. It is Windows-centric; IKEv2 and OpenVPN-style TLS VPNs are the alternatives." },
  "TACACS+": { full: "Terminal Access Controller Access-Control System Plus", tip: "Cisco's AAA protocol for device administration on TCP 49; encrypts the whole payload and separates authentication from authorization.", more: "TACACS+ is used to control who can log in to routers and switches and which commands they may run. Compared with RADIUS it uses TCP, encrypts the entire packet, and handles authorization command by command, which suits administrative access rather than user network access." },
  "TB": { full: "Terabyte", tip: "About a trillion bytes; the unit for large drives.", more: "Drives are sold in TB. MBR cannot address more than 2 TB, which is one reason GPT exists." },
  "TCP": { full: "Transmission Control Protocol", tip: "Reliable, ordered, connection-based transport: three-way handshake, acknowledgments, retransmission.", more: "TCP sets up a connection with a SYN, SYN-ACK, ACK handshake, numbers every segment, acknowledges what arrives, and resends what does not. That reliability costs overhead, so it suits web pages, email, and file transfer rather than live voice. Port numbers at Layer 4 identify which application on the host the data is for." },
  "TGT": { full: "Ticket-granting ticket", tip: "The Kerberos ticket a user receives at logon, used to request tickets for services.", more: "The TGT proves the user authenticated to the KDC. It is presented to obtain service tickets without re-entering the password, and it expires, which is why clock skew breaks logons." },
  "TKIP": { full: "Temporal Key Integrity Protocol", tip: "WPA's per-packet keying scheme; deprecated.", more: "TKIP wrapped the old RC4 cipher with changing keys so WEP hardware could be patched. It is now considered broken and WPA2 with AES-CCMP or WPA3 should be used instead." },
  "TLS": { full: "Transport Layer Security", tip: "The encryption layer under HTTPS and most secure protocols; use 1.2 or 1.3.", more: "TLS authenticates the server with a certificate, agrees session keys, and then encrypts the connection. It replaced SSL, whose versions are all deprecated. TLS 1.0 and 1.1 are also retired. It works at the presentation and session layers in OSI terms and protects web, mail, LDAP, and VPN traffic." },
  "TOTP": { full: "Time-based one-time password", tip: "A six-digit code from an authenticator app that changes every 30 seconds.", more: "TOTP derives the code from a shared secret and the current time, so the server can verify it without a network connection to the phone. It is the something-you-have factor in most MFA." },
  "TPM": { full: "Trusted Platform Module", tip: "A security chip on the motherboard that stores keys and measurements; required for BitLocker and Windows 11.", more: "The TPM holds encryption keys that never leave the chip and records boot measurements so it can refuse to release keys if the firmware or boot loader changed. Full-disk encryption keys, device identity certificates, and attestation all rely on it." },
  "TRIM": { full: "TRIM command", tip: "Tells an SSD which blocks are no longer in use so it can erase them ahead of time.", more: "Without TRIM an SSD slows down as it fills, because it must erase blocks before writing. Modern operating systems send TRIM automatically; never defragment an SSD." },
  "UAC": { full: "User Account Control", tip: "The Windows prompt that asks for consent or an administrator password before a privileged change.", more: "UAC runs even administrators with standard rights until they approve an elevation, which limits what malware can silently do. Turning it off is a security finding." },
  "UDP": { full: "User Datagram Protocol", tip: "Connectionless, fast transport with no delivery guarantee; used for voice, video, DNS, DHCP.", more: "UDP sends datagrams without a handshake, without acknowledgments, and without retransmission. That makes it fast and light, which is what real-time voice and video want, since a late packet is useless anyway. DNS queries, DHCP, TFTP, SNMP, and syslog also ride on UDP." },
  "UEFI": { full: "Unified Extensible Firmware Interface", tip: "Modern firmware that replaces BIOS: GPT disks, Secure Boot, mouse-driven setup.", more: "UEFI boots from GPT disks of any size, verifies boot loaders with Secure Boot, and offers a graphical setup. A compatibility mode (CSM) boots legacy BIOS-style systems. Windows 11 requires UEFI with Secure Boot and a TPM." },
  "UID": { full: "User identifier", tip: "The number Linux uses to identify each user account.", more: "Root is UID 0. File ownership and permissions are stored by UID, which is why copying files between systems can shift ownership." },
  "UNC": { full: "Universal Naming Convention", tip: "The \\\\server\\share path format for network resources.", more: "A UNC path names a share directly, such as \\\\fileserver\\public, and works whether or not a drive letter is mapped." },
  "UPS": { full: "Uninterruptible power supply", tip: "A battery unit that keeps equipment running through a power cut and conditions the power.", more: "A UPS sits between the wall and the equipment, taking over instantly when power fails and giving time to shut down or for a generator to start. It is sized in VA or watts against the load for the runtime needed. In medical settings a UPS covers the transfer gap to emergency power." },
  "URL": { full: "Uniform resource locator", tip: "A web address such as https://www.example.com/page.", more: "The URL names the protocol, host, port, path, and query. URL filtering blocks sites by address or category; attackers hide malicious URLs behind look-alike domains and shortened links." },
  "USB": { full: "Universal Serial Bus", tip: "The standard port for peripherals, storage, and charging.", more: "USB versions set speed: 2.0 at 480 Mbps, 3.0 at 5 Gbps, 3.1 at 10 Gbps, 3.2 at 20 Gbps, USB4 at 40 Gbps. Connectors include A, B, mini, micro, and the reversible C. Unknown USB drives are a malware vector, which DLP and device control address." },
  "VLAN": { full: "Virtual local area network", tip: "A logical LAN on a switch: ports in different VLANs are separate broadcast domains.", more: "A VLAN splits one physical switch into several logical switches. Ports in VLAN 10 cannot talk to ports in VLAN 20 without a router or Layer 3 switch, which contains broadcasts and separates traffic such as voice, data, and guests. Trunk links carry many VLANs between switches using 802.1Q tags. A native VLAN is the untagged one on a trunk, and a voice VLAN lets a phone tag its traffic while the PC behind it stays untagged." },
  "VM": { full: "Virtual machine", tip: "A complete computer running as software on a hypervisor.", more: "A VM has its own operating system and virtual hardware but shares the physical host with others. Type 1 hypervisors run on bare metal; type 2 run on a host OS. VM escape, where code in a guest reaches the host, is the serious virtualization vulnerability; VM sprawl is the management one." },
  "VNC": { full: "Virtual Network Computing", tip: "A cross-platform remote desktop protocol.", more: "VNC shares a screen and control across Windows, macOS, and Linux. It should be tunneled or protected because basic VNC has weak security." },
  "VPN": { full: "Virtual private network", tip: "An encrypted tunnel across an untrusted network such as the internet.", more: "A VPN makes a remote user or site appear to be on the private network by encrypting traffic between the endpoints. Site-to-site VPNs join offices, usually with IPsec; remote-access VPNs connect individual users with IPsec or TLS clients. Split tunneling sends only corporate traffic through the tunnel; full tunneling sends everything." },
  "VRAM": { full: "Video RAM", tip: "The memory on a graphics card that holds frames and textures.", more: "VRAM capacity limits the resolution and detail a GPU can handle. Integrated graphics borrow system RAM instead." },
  "WAN": { full: "Wide area network", tip: "Connects LANs across cities or countries, usually over links leased from a provider.", more: "A WAN joins sites that are far apart. Because the organization cannot run its own cable between cities, it rents circuits or internet connections from a carrier, which is why WAN links are slower and cost per month. The internet is the largest WAN. Routers sit at the edge of each site to send traffic across the WAN." },
  "WEP": { full: "Wired Equivalent Privacy", tip: "The original Wi-Fi encryption, broken in minutes; never use it.", more: "WEP used the RC4 cipher with short, badly managed keys, and tools can recover the key from captured traffic in minutes. Any question describing WEP wants you to replace it with WPA2 or WPA3." },
  "Wi-Fi": { full: "Wireless fidelity", tip: "The trade name for IEEE 802.11 wireless networking.", more: "Wi-Fi is the brand the Wi-Fi Alliance gives to interoperable 802.11 equipment. Generations are numbered: Wi-Fi 4 is 802.11n, Wi-Fi 5 is 802.11ac, Wi-Fi 6 and 6E are 802.11ax (6E adds the 6 GHz band), and Wi-Fi 7 is 802.11be. Bands are 2.4 GHz (range, interference), 5 GHz (speed, more channels), and 6 GHz." },
  "WLAN": { full: "Wireless local area network", tip: "A LAN delivered over Wi-Fi instead of cables.", more: "A WLAN is the same idea as a LAN, but the clients connect by radio to access points instead of by cable to a switch. The access points still plug into the wired LAN, so a WLAN is an extension of the LAN rather than a separate network. Wi-Fi is the family of standards (IEEE 802.11) that most WLANs use." },
  "WMI": { full: "Windows Management Instrumentation", tip: "The Windows framework for querying and managing system information, used by scripts and monitoring tools.", more: "WMI exposes hardware, software, and settings to PowerShell and management agents. Attackers also use it for stealthy persistence, so its activity is worth logging." },
  "WPA": { full: "Wi-Fi Protected Access", tip: "The interim fix for WEP that used TKIP; deprecated.", more: "WPA kept WEP-era hardware working by adding per-packet keys with TKIP. It was a stopgap until WPA2 brought AES and is now considered insecure." },
  "WPA2": { full: "Wi-Fi Protected Access 2", tip: "Wi-Fi security using AES with CCMP; still common and acceptable.", more: "WPA2 replaced TKIP with AES-CCMP encryption. Personal mode uses a pre-shared passphrase; Enterprise mode authenticates each user through 802.1X and RADIUS. Its weakness is that a captured handshake can be attacked offline with password guessing, which WPA3 fixes." },
  "WPA3": { full: "Wi-Fi Protected Access 3", tip: "The current Wi-Fi security standard: SAE in Personal mode, stronger encryption, protected management frames.", more: "WPA3 Personal replaces the pre-shared key handshake with SAE (simultaneous authentication of equals), which stops offline password cracking and adds forward secrecy. Enterprise mode still uses 802.1X. Protected management frames are mandatory, blocking deauthentication attacks." },
  "WPAD": { full: "Web Proxy Auto-Discovery", tip: "Lets a browser find its proxy settings automatically through DHCP or DNS.", more: "WPAD looks up a configuration script by name. A rogue WPAD server on the network can redirect all web traffic through an attacker, so many organizations disable it." },
  "WS-Management": { full: "Web Services for Management", tip: "The standard protocol behind Windows Remote Management and PowerShell remoting.", more: "WS-Management carries management commands over HTTP or HTTPS. Windows implements it as WinRM, which PowerShell remoting uses on ports 5985 and 5986." },
  "WWAN": { full: "Wireless wide area network", tip: "Cellular data connectivity, such as a laptop's built-in LTE or 5G modem.", more: "A WWAN card gives a laptop internet anywhere there is cellular coverage, with its own SIM." },
  "XDR": { full: "Extended detection and response", tip: "EDR extended across endpoints, network, cloud, and email into one correlated view.", more: "XDR pulls detections from many sources together so an attack that touches email, an endpoint, and a server shows as one incident." },
  "XFS": { full: "XFS file system", tip: "A high-performance journaling file system used by Red Hat Enterprise Linux and others.", more: "XFS handles very large files and volumes well and is the default on RHEL. It cannot be shrunk once created." },
  "XSS": { full: "Cross-site scripting", tip: "An attacker's script runs in other users' browsers because a site echoes untrusted input.", more: "In XSS the attacker stores or reflects script through a web page so that it executes in the victim's browser, stealing sessions or acting as the user. Input validation and output encoding are the defenses." }
};
// Uppercase words in the course text that are not acronyms (emphasis, registry key names, model numbers, formula symbols).
FRA.acronymIgnore = ["BEFORE","BEST","DOMAIN","FIRST","FS01","LAST","LEAST","MAIN","MOST","NET","NEXT","NO","NOT","OR","SOFTWARE"];
